      }
    }
  }
  scf.for %arg0 = %c0 to %c2 step %c1 {
    scf.for %arg1 = %c0 to %c6 step %c1 {
      %9 = memref.load %1[%arg0, %arg1] : memref<2x6xf32, #amdgpu.address_space<fat_raw_buffer>>
      %10 = memref.load %3[%arg0, %arg1] : memref<2x6xi32, #amdgpu.address_space<fat_raw_buffer>>
      %11:2 = scf.for %arg2 = %c0 to %c3 step %c1 iter_args(%arg3 = %9, %arg4 = %10) -> (f32, i32) {
        %12 = memref.load %5[%arg0, %arg2] : memref<2x3xf32, #amdgpu.address_space<fat_raw_buffer>>
        %13 = memref.load %7[%arg0, %arg2] : memref<2x3xi32, strided<[3, 1]>, #amdgpu.address_space<fat_raw_buffer>> // <- does the store above happen-before this?
